// th15_s2_w07 -- TH15 st02 MainSub05 中Boss后蓝幽灵三轮9对
// 源: st02.ecl.txt:1056-1075 (MainSub05 入口段), 1196-1203 (Phantom01B),
//     1176-1194 (Phantom01), 1214-1234 (Phantom01_at)
// 源 phase: wait(100) 后 3 轮 x 9 对, 每对间隔 30 帧; 本卡在 120 帧缓冲后从 wait(100) 起跑.

const TIME_LIMIT: int = 2424;      // 120 缓冲 + 2300 窗口 + 4 启动余量
const OPENING_BUFFER: int = 120;
const TH15_RING_BALL2: int = 464;  // 源 etSprite type 7 -> TH15_RING_BALL2, color 2

// Phantom01/Phantom01B: 无出生动画, 框 28/16 走普通圆形分支 -> 半径 14/8.
// Phantom01 的 moveEllipseRel(F0=0, ω=2°/帧, r=10, d=0, β=ABS_ANGLE=90°, s=0)
// 退化为 REL 横向正弦: x = x0 + 10*cos(θ), θ 每帧 +2°; 纵向是 ABS 的
// moveVelTime(120, mode3, 90°, 1.0), 即 0.5 -> 1.0 的 quart-in.
// 目标没有 REL 层, 显式积分后逐帧写最终位置. 源 flagSet(12) 只关屏外回收,
// 目标敌不按屏外回收, 故省略.
async sub phantom(x0: fx) {
    set_invuln(65535);
    set_hurtbox(14fx);
    set_hitbox(8fx);
    move_to(0, x0 + 10fx, -24fx, EASE_LINEAR);   // 椭圆 setter 设置当下 θ=0
    spawn phantom_shots();
    var theta: angle = 0deg;
    var y: fx = -24fx;
    var k: int = 0;
    loop {
        wait(1);
        k = k + 1;
        var v: fx = 1fx;
        if k <= 120 {
            var u: fx = (k as fx) / 120fx;
            v = 0.5fx + 0.5fx * u * u * u * u;
        }
        y = y + v;
        theta = theta + 2deg;
        move_to(0, x0 + 10fx * cos(theta), y, EASE_LINEAR);
    }
}

// Phantom01_at: etAim(0,0)=自机狙单路; etCountD 路数1/层数 E1 N2 H4 L8;
// etSpeedD 首末层速 E1/1, N2/0.8, H3/1, L4/1; diffI($A,1,1,2,3) 次齐射.
// etEx type2 a=1 是出生 ANIM: 出生动画省略, 但退位移 position -= 4*velocity 保留.
// 第二次 etEx 是 WAIT a=0, 直接前进, 无持续效果.
async sub phantom_shots() {
    var rank: int = global(GVAR_RANK);
    var layers: int = 1;
    var s0: fx = 1fx;
    var step: fx = 0fx;
    var bursts: int = 1;
    if rank == 1 { layers = 2; s0 = 2fx; step = -1.2fx; }
    if rank == 2 { layers = 4; s0 = 3fx; step = -0.6666667fx; bursts = 2; }
    if rank == 3 { layers = 8; s0 = 4fx; step = -0.4285714fx; bursts = 3; }
    for b in 0..bursts {
        wait(20 + rand(200));          // 源 wait(20 + ($RAND % 200))
        var aim: angle = aim_player(); // 源整波只取一次自机角
        for q in 0..layers {
            var sp: fx = s0 + step * (q as fx);
            _ = fire(TH15_RING_BALL2, 2,
                     $self_x - 4fx * sp * cos(aim),
                     $self_y - 4fx * sp * sin(aim),
                     sp, aim, none, none);
        }
    }
}

// MainSub05 排程: wait(100) 后三轮, 每轮 %A 从 0 每对 +16 (16..144),
// enmCreate / enmCreateM 对称在 ±A, y=-24; 每对后 wait(30).
async sub pattern() {
    wait(OPENING_BUFFER);
    wait(100);
    for wave in 0..3 {
        var x: fx = 0fx;
        for i in 0..9 {
            x = x + 16fx;
            _ = spawn_enemy(x, -24fx, 1000, 0, 0, 0, phantom(x));
            _ = spawn_enemy(0fx - x, -24fx, 1000, 0, 0, 0, phantom(0fx - x));
            wait(30);
        }
    }
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
